// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCoupon, getCoupon, getCouponsList } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    // This test is about the auth gate itself, so it deliberately sends NO
    // Authorization header — the empty map is the point of the test, not an
    // oversight, and it holds whether or not SKYRAMP_TEST_TOKEN is set.
    const headers: Record<string, string> = {};

    const couponsGetResponse = await getCouponsList(client, headers, 401);
    expect(couponsGetResponse.statusCode, 'status code').toBe(401);
    expect(getResponseValue(couponsGetResponse, "response"), 'error message').toBe("You must be logged in.");
    expect(getResponseValue(couponsGetResponse, "response.0"), 'no coupon list is returned to an anonymous caller').toBeNull();

    const couponsPostResponse = await createCoupon(client, headers, "TESTBOT-NOAUTH", 10, 401);
    expect(couponsPostResponse.statusCode, 'status code').toBe(401);
    expect(getResponseValue(couponsPostResponse, "response"), 'error message').toBe("You must be logged in.");
    expect(getResponseValue(couponsPostResponse, "response.id"), 'no coupon is created for an anonymous caller').toBeNull();

    const coupons1GetResponse = await getCoupon(client, headers, "1", 401);
    expect(coupons1GetResponse.statusCode, 'status code').toBe(401);
    expect(getResponseValue(coupons1GetResponse, "response"), 'error message').toBe("You must be logged in.");
    expect(getResponseValue(coupons1GetResponse, "response.code"), 'no coupon is disclosed to an anonymous caller').toBeNull();
    expect(getResponseValue(coupons1GetResponse, "response.discountPercent"), 'no coupon is disclosed to an anonymous caller').toBeNull();
});
